-- Dockly · canales, ríos y el Intracoastal de Fort Lauderdale, bajados de OpenStreetMap (ODbL) el 8 de noviembre de 2026.
-- Volver a correr es seguro: hace upsert por osm_id y después regenera el grafo. Las zanjas (ditch) quedan no navegables.
on conflict (osm_id) do update set name = excluded.name, kind = excluded.kind, navigable = excluded.navigable, geom = excluded.geom;
select rebuild_water_graph();
